import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

triu_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor triu_matmul(torch::Tensor A, torch::Tensor B);
"""

triu_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_pipeline.h>
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
#define TRIU_CP_ASYNC 1
#else
#define TRIU_CP_ASYNC 0
#endif

#include <cute/tensor.hpp>

using namespace cute;

// C = triu(A @ B) for upper triangular A, B (row-major N x N).
// One fused kernel: tiled GEMM + triangular masking, exploiting that
// A[m,k] = 0 for k < m and B[k,n] = 0 for k > n.
template <typename T>
__global__ static void triu_gemm_kernel(const T* __restrict__ Ap,
                                        const T* __restrict__ Bp,
                                        T* __restrict__ Cp,
                                        int N)
{
  const int bx  = blockIdx.x;   // M-tile index
  const int by  = blockIdx.y;   // N-tile index
  const int tid = threadIdx.x;

  // Full tensors: A (M,K), B (K,N), C (M,N), all row-major
  Tensor mA = make_tensor(make_gmem_ptr(Ap), make_shape(N, N), make_stride(N, Int<1>{}));
  Tensor mB = make_tensor(make_gmem_ptr(Bp), make_shape(N, N), make_stride(N, Int<1>{}));
  Tensor mC = make_tensor(make_gmem_ptr(Cp), make_shape(N, N), make_stride(N, Int<1>{}));

  auto cta_tiler = make_shape(Int<128>{}, Int<128>{}, Int<8>{});
  auto cta_coord = make_coord(bx, by, _);

  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1,_1, X>{});  // (128,128)

  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}));             // 256 threads
  Tensor tCgC = local_partition(gC, tC, tid);                          // (8,8)

  // Tiles entirely below the diagonal are exactly zero after triu.
  if (bx > by) {
    clear(tCgC);
    return;
  }

  Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1, X,_1>{});  // (128,8,kt)
  Tensor gB = local_tile(mB, make_shape(Int<8>{}, Int<128>{}), make_coord(_, by));  // (8,128,kt)

  // Double-buffered shared memory staging: prefetch K-tile kt+1 while the
  // current tile is being consumed by the gemm (software pipelining).
  __shared__ T smemA[2][128 * 8];
  __shared__ T smemB[2][8 * 132];
  // Swizzled (M,K) shared layout. With 8 rows per thread, any plain
  // padded row stride s makes 8*s a multiple of the 32-bank period, so
  // all 16 distinct A addresses in a warp hit one bank (16-way conflict).
  // Swizzle<3,2,4> XORs the 16B-chunk index with the row index, cutting
  // this to a 2-way conflict while preserving 16B chunk granularity.
  auto sA_layout = composition(Swizzle<3,2,4>{},
                               make_layout(make_shape(Int<128>{}, Int<8>{}),
                                           make_stride(Int<8>{}, Int<1>{})));
  // Transposed view of sB so gemm gets B as (N,K); K stride is 132 (not 128)
  auto sBt_layout = make_layout(make_shape(Int<128>{}, Int<8>{}),
                                make_stride(Int<1>{}, Int<132>{}));  // (N,K)
  // Vectorized gmem->smem staging: one 16B float4 per thread per operand tile.
  const int a_row  = tid >> 1;            // 0..127 rows of sA
  const int a_col4 = (tid & 1) * 4;       // two float4 per 8-wide K row
  const int b_row  = tid >> 5;            // 0..7 rows of sB
  const int b_col4 = (tid & 31) * 4;      // 32 float4 per 128-wide N row
  // Swizzled 16B smem slot for this thread's A fragment (swizzle keeps
  // 16B chunks intact, so float4/cp.async staging stays valid).
  const int a_off = (int)sA_layout(a_row, a_col4);
  Tensor tCrC = make_fragment_like(tCgC);       // (8,8) accumulators
  clear(tCrC);
  // Only K-tiles covering k in [128*bx, 128*by+127] can contribute:
  // A needs k >= m >= bx*128, B needs k <= n <= by*128+127.
  // Each 128-wide CTA tile spans 128/8 = 16 of the 8-wide K-tiles.
  constexpr int kKTilesPerCta = 128 / 8;   // 16
  const int kt_begin = bx * kKTilesPerCta;
  const int kt_end   = (by + 1) * kKTilesPerCta;
  // Asynchronous staging with cp.async (sm_80+): global->shared copies
  // bypass the register file, so the prefetch of K-tile kt+1 fully
  // overlaps with the gemm on tile kt (hardware async pipeline).
  auto stage_tile = [&](int kt, int buf) {
    const float4* gA4 = reinterpret_cast<const float4*>(
        Ap + (size_t)(bx * 128 + a_row) * N + kt * 8 + a_col4);
    const float4* gB4 = reinterpret_cast<const float4*>(
        Bp + (size_t)(kt * 8 + b_row) * N + by * 128 + b_col4);
#if TRIU_CP_ASYNC
    __pipeline_memcpy_async(&smemA[buf][a_off], gA4, 16);
    __pipeline_memcpy_async(&smemB[buf][b_row * 132 + b_col4], gB4, 16);
#else
    *reinterpret_cast<float4*>(&smemA[buf][a_off]) = *gA4;
    *reinterpret_cast<float4*>(&smemB[buf][b_row * 132 + b_col4]) = *gB4;
#endif
  };
  // Prologue: asynchronously stage the first K-tile.
  stage_tile(kt_begin, 0);
#if TRIU_CP_ASYNC
  __pipeline_commit();
#endif
  // Main pipelined loop: keep one cp.async tile in flight while the
  // gemm consumes the current tile from the other buffer.
  for (int kt = kt_begin; kt < kt_end; ++kt) {
    const int buf = (kt - kt_begin) & 1;
    if (kt + 1 < kt_end) {
      stage_tile(kt + 1, buf ^ 1);   // prefetch next tile into other buffer
#if TRIU_CP_ASYNC
      __pipeline_commit();
      __pipeline_wait_prior(1);      // tile kt ready; kt+1 stays in flight
#endif
    }
#if TRIU_CP_ASYNC
    else {
      __pipeline_wait_prior(0);      // drain: no prefetch outstanding
    }
#endif
    __syncthreads();
    Tensor sA  = make_tensor(make_smem_ptr(smemA[buf]), sA_layout);
    Tensor sBt = make_tensor(make_smem_ptr(smemB[buf]), sBt_layout);
    Tensor tCsA = local_partition(sA,  tC, tid, Step<_1, X>{});  // (8,8)
    Tensor tCsB = local_partition(sBt, tC, tid, Step< X,_1>{});  // (8,8)
    gemm(tCsA, tCsB, tCrC);
    __syncthreads();
  }

  if (bx == by) {
    // Diagonal tile: apply the triu mask in the epilogue.
    Tensor cC   = make_identity_tensor(make_shape(Int<128>{}, Int<128>{}));
    Tensor tCcC = local_partition(cC, tC, tid);
    const int m_base = bx * 128;
    const int n_base = by * 128;
    CUTE_UNROLL
    for (int i = 0; i < size(tCrC); ++i) {
      auto coord = tCcC(i);
      int m = m_base + get<0>(coord);
      int n = n_base + get<1>(coord);
      tCgC(i) = (m <= n) ? tCrC(i) : T(0);
    }
  } else {
    // Strictly above-diagonal tile: every element is kept.
    copy(tCrC, tCgC);
  }
}

torch::Tensor triu_matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");

  int64_t N = A.size(0);
  TORCH_CHECK(A.size(1) == N && B.size(0) == N && B.size(1) == N,
              "A and B must be square N x N with the same N");
  TORCH_CHECK(N % 128 == 0, "N must be a multiple of 128");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C   = torch::empty({N, N}, A.options());

  dim3 block(256);
  dim3 grid((unsigned)(N / 128), (unsigned)(N / 128));

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  triu_gemm_kernel<float><<<grid, block, 0, stream>>>(
      A_c.data_ptr<float>(),
      B_c.data_ptr<float>(),
      C.data_ptr<float>(),
      (int)N);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "triu_gemm_kernel launch failed: ",
              cudaGetErrorString(err));

  return C;
}
"""

triu_ext = load_inline(
    name="cute_triu_gemm_ext",
    cpp_sources=triu_cpp_decl,
    cuda_sources=triu_cuda_src,
    functions=["triu_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute",
    ],
    verbose=False,
